#!/usr/bin/env bun

// HYP-001 Validation: Test Bun's built-in YAML parsing
console.log("=== HYP-001: Testing Bun Built-in YAML Parsing ===\n");

// Test 1: Check if Bun.YAML is available
console.log("Test 1: Checking Bun.YAML availability...");
try {
  console.log("  Bun.YAML:", typeof Bun.YAML);
  console.log("  Bun.YAML.parse:", typeof Bun.YAML.parse);
  console.log("  ✓ Bun.YAML is available\n");
} catch (error) {
  console.log("  ✗ Bun.YAML not available:", error);
  process.exit(1);
}

// Test 2: Parse valid YAML with standard features
console.log("Test 2: Parsing valid YAML...");
const validYaml = `
name: test-project
version: 1.0.0
items:
  - one
  - two
  - three
nested:
  key: value
  number: 42
  boolean: true
`;

try {
  const result = Bun.YAML.parse(validYaml);
  console.log("  Parsed result:", JSON.stringify(result, null, 2));
  console.log("  ✓ Valid YAML parsed successfully\n");
} catch (error) {
  console.log("  ✗ Failed to parse valid YAML:", error);
  process.exit(1);
}

// Test 3: Test error handling with invalid YAML
console.log("Test 3: Testing error handling with invalid YAML...");
const invalidYaml = `
name: test
  invalid indentation
version: 1.0.0
`;

try {
  const result = Bun.YAML.parse(invalidYaml);
  console.log("  ✗ Should have thrown error but got:", result);
} catch (error) {
  console.log("  ✓ Invalid YAML throws error as expected");
  console.log("  Error type:", error.constructor.name);
  console.log("  Error message:", error.message);
  console.log("");
}

// Test 4: Can we use it without installing any packages?
console.log("Test 4: Verifying no external dependencies needed...");
console.log("  This script uses Bun.YAML without any imports from node_modules");
console.log("  ✓ No external dependencies required\n");

console.log("=== HYP-001 VALIDATION: CONFIRMED ===");
console.log("Bun provides built-in YAML parsing via Bun.YAML.parse()");

#!/usr/bin/env bun

// HYP-002 Validation: Test if parser errors include line/column information
console.log("=== HYP-002: Testing YAML Parser Error Location Information ===\n");

const invalidSamples = [
  {
    name: "indentation-error",
    yaml: "name: test\n  bad indent\nversion: 1.0.0",
    expectedLine: 2
  },
  {
    name: "unclosed-quote",
    yaml: 'name: "unclosed\nversion: 1.0.0',
    expectedLine: 1
  },
  {
    name: "invalid-character",
    yaml: "name: test\nversion: 1.0.0\n@invalid",
    expectedLine: 3
  },
  {
    name: "duplicate-key",
    yaml: "name: test\nname: duplicate\nversion: 1.0.0",
    expectedLine: 2
  },
  {
    name: "tab-character",
    yaml: "name: test\n\tversion: 1.0.0",
    expectedLine: 2
  }
];

let hasLineInfo = false;
let hasColumnInfo = false;
let errorStructures: any[] = [];

console.log("Testing various invalid YAML samples...\n");

for (const sample of invalidSamples) {
  console.log(`Sample: ${sample.name}`);
  console.log(`YAML:\n${sample.yaml.split('\n').map((l, i) => `  ${i + 1}: ${l}`).join('\n')}`);

  try {
    Bun.YAML.parse(sample.yaml);
    console.log("  ✗ Should have thrown error\n");
  } catch (error: any) {
    console.log("  ✓ Error thrown as expected");
    console.log("  Message:", error.message);

    // Check error object structure
    const errorKeys = Object.keys(error);
    console.log("  Error object keys:", errorKeys);

    // Check for line/column properties
    if ('line' in error) {
      console.log("  Line:", error.line);
      hasLineInfo = true;
    }
    if ('column' in error || 'col' in error) {
      console.log("  Column:", error.column || error.col);
      hasColumnInfo = true;
    }

    // Check if message contains location info
    const messageHasLine = /line\s+\d+/i.test(error.message);
    const messageHasCol = /col(umn)?\s+\d+/i.test(error.message);

    if (messageHasLine || messageHasCol) {
      console.log("  Location in message: YES");
      hasLineInfo = hasLineInfo || messageHasLine;
      hasColumnInfo = hasColumnInfo || messageHasCol;
    }

    errorStructures.push({
      sample: sample.name,
      message: error.message,
      hasLineProperty: 'line' in error,
      hasColumnProperty: 'column' in error || 'col' in error,
      messageIncludesLocation: messageHasLine || messageHasCol
    });

    console.log("");
  }
}

console.log("=== SUMMARY ===");
console.log("Total samples tested:", invalidSamples.length);
console.log("Line information available:", hasLineInfo ? "YES" : "NO");
console.log("Column information available:", hasColumnInfo ? "YES" : "NO");
console.log("\nDetailed error structures:");
console.log(JSON.stringify(errorStructures, null, 2));

if (hasLineInfo) {
  console.log("\n=== HYP-002 VALIDATION: CONFIRMED ===");
  console.log("Parser errors include location information");
} else {
  console.log("\n=== HYP-002 VALIDATION: REJECTED ===");
  console.log("Parser errors do NOT include reliable location information");
}

#!/usr/bin/env bun

// Verify line/column accuracy for errors that DO get thrown
console.log("=== Testing Line/Column Accuracy ===\n");

const testCases = [
  {
    name: "unclosed-quote-line-1",
    yaml: 'name: "unclosed',
    expectedLine: 1
  },
  {
    name: "unclosed-quote-line-3",
    yaml: 'name: test\nversion: 1.0.0\nkey: "unclosed',
    expectedLine: 3
  },
  {
    name: "colon-in-unquoted-string",
    yaml: 'name: test: invalid',
    expectedLine: 1
  },
  {
    name: "syntax-error-multi-line",
    yaml: 'name: test\nversion: 1.0.0\nitems:\n  - one\n  - "unclosed',
    expectedLine: 5
  }
];

console.log("Testing error line/column accuracy...\n");

for (const test of testCases) {
  console.log(`Test: ${test.name}`);
  console.log(`Expected error on line ${test.expectedLine}`);
  console.log(`YAML content:\n${test.yaml.split('\n').map((l, i) => `  ${i + 1}: ${l}`).join('\n')}`);

  try {
    Bun.YAML.parse(test.yaml);
    console.log("  ✗ No error thrown\n");
  } catch (error: any) {
    console.log(`  ✓ Error thrown`);
    console.log(`  Line: ${error.line}, Column: ${error.column}`);
    console.log(`  Message: ${error.message}`);

    // Note: error.line and error.column appear to be from the stack trace location,
    // not the YAML content. Let's extract from message if possible.
    const match = error.message.match(/line[:\s]+(\d+)|column[:\s]+(\d+)/i);
    if (match) {
      console.log(`  Location extracted from message: ${match[0]}`);
    }
    console.log("");
  }
}

// Test what Bun.YAML.parse returns vs throws
console.log("\n=== Understanding Parser Behavior ===\n");

const permissiveCases = [
  "name: test\n  indented text",  // This was accepted before
  "name: test\nname: duplicate",   // Duplicate keys
  "name: test\n\tversion: 1.0.0"   // Tabs (usually invalid in YAML)
];

for (let i = 0; i < permissiveCases.length; i++) {
  console.log(`Permissive case ${i + 1}:`);
  console.log(permissiveCases[i].replace(/\t/g, '<TAB>'));
  try {
    const result = Bun.YAML.parse(permissiveCases[i]);
    console.log("  Parsed successfully:", JSON.stringify(result));
  } catch (error: any) {
    console.log("  Error:", error.message);
  }
  console.log("");
}

#!/usr/bin/env bun

// Deep inspection of error object structure
console.log("=== Deep Error Object Inspection ===\n");

const invalidYaml = 'name: "unclosed\nkey: value';

try {
  Bun.YAML.parse(invalidYaml);
} catch (error: any) {
  console.log("Error caught. Inspecting structure...\n");

  console.log("typeof error:", typeof error);
  console.log("error.constructor.name:", error.constructor.name);
  console.log("\nDirect properties:");
  console.log("  message:", error.message);
  console.log("  name:", error.name);
  console.log("  stack:", error.stack?.substring(0, 200) + "...");

  console.log("\nAll enumerable properties:");
  for (const key in error) {
    console.log(`  ${key}:`, error[key]);
  }

  console.log("\nAll own property names:");
  const allKeys = Object.getOwnPropertyNames(error);
  for (const key of allKeys) {
    try {
      const value = error[key];
      if (typeof value !== 'function' && key !== 'stack') {
        console.log(`  ${key}:`, value);
      }
    } catch (e) {
      console.log(`  ${key}: <getter error>`);
    }
  }

  console.log("\nChecking prototype chain:");
  let proto = Object.getPrototypeOf(error);
  let depth = 0;
  while (proto && depth < 5) {
    console.log(`  Prototype ${depth}:`, proto.constructor?.name);
    const protoKeys = Object.getOwnPropertyNames(proto);
    for (const key of protoKeys) {
      if (!['constructor', 'toString', 'valueOf'].includes(key)) {
        console.log(`    - ${key}`);
      }
    }
    proto = Object.getPrototypeOf(proto);
    depth++;
  }

  console.log("\n\nFull error object stringified:");
  console.log(JSON.stringify(error, null, 2));

  console.log("\n\nError.line and Error.column values:");
  console.log("  line:", error.line, "(type:", typeof error.line, ")");
  console.log("  column:", error.column, "(type:", typeof error.column, ")");
  console.log("  col:", error.col);

  // Check if error message contains extractable location info
  console.log("\n\nMessage analysis:");
  console.log("  Full message:", error.message);
  const lineMatch = error.message.match(/line[:\s]+(\d+)/i);
  const colMatch = error.message.match(/col(?:umn)?[:\s]+(\d+)/i);
  console.log("  Line number in message:", lineMatch?.[1] || "NOT FOUND");
  console.log("  Column number in message:", colMatch?.[1] || "NOT FOUND");
}

#!/usr/bin/env bun

// Test originalLine and originalColumn accuracy
console.log("=== Testing originalLine and originalColumn Properties ===\n");

const testCases = [
  {
    name: "error-on-line-1",
    yaml: 'name: "unclosed',
    expectedLine: 1
