      console.log(`    Accuracy: ${accurate ? '✓ CORRECT' : '✗ INCORRECT'} (expected line ${test.expectedLine})`);
      if (!accurate) allAccurate = false;
    } else {
      console.log(`    ✗ Missing originalLine/originalColumn properties`);
      allAccurate = false;
    }
  }
}

console.log("\n\n=== FINAL RESULT ===");
