  console.log("✓ originalLine and originalColumn provide accurate YAML location information");
  console.log("\nHYP-002 CONFIRMED:");
  console.log("- Errors include line/column via 'originalLine' and 'originalColumn' properties");
  console.log("- These properties accurately point to the error location in the YAML content");
  console.log("- Note: 'line' and 'column' properties are JavaScript stack locations, not YAML");
} else {
