/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Validation result for YAML files.
 */
export interface ValidationResult {
  /** Whether the YAML is syntactically valid */
  valid: boolean;

  /** Error message if validation failed */
  error?: string;

  /** Line number where error occurred (if available) */
  line?: number;

  /** Column number where error occurred (if available) */
  column?: number;
}

/**
 * Validate YAML file syntax.
 *
 * @param filePath - Absolute or relative path to YAML file
 * @returns Validation result with error details if invalid
 *
 * @example
 * ```typescript
 * const result = await validateYaml('config.yaml');
 * if (result.valid) {
 *   console.log('Valid YAML');
 * } else {
 *   console.error(`Error at line ${result.line}: ${result.error}`);
 * }
 * ```
 */
export async function validateYaml(filePath: string): Promise<ValidationResult> {
  try {
    // Read file content using Bun.file API
    const file = Bun.file(filePath);
    const content = await file.text();

    // Parse YAML using Bun's built-in capabilities
    // Bun doesn't have a dedicated YAML parser, but we can use the YAML parsing
    // capability through dynamic import or try parsing
    try {
      // Use Bun's built-in YAML parsing via import
      const yaml = await import('yaml');
      yaml.parse(content);

      return { valid: true };
    } catch (parseError) {
      // Extract error details
      const error = parseError as Error;
      let line: number | undefined;
      let column: number | undefined;

      // Try to extract line and column numbers from error message
      // Common format: "Error at line X, column Y"
      const lineMatch = error.message.match(/line[:\s]+(\d+)/i);
      const columnMatch = error.message.match(/column[:\s]+(\d+)/i);

      if (lineMatch) {
        line = parseInt(lineMatch[1], 10);
      }
      if (columnMatch) {
        column = parseInt(columnMatch[1], 10);
      }

      return {
        valid: false,
        error: error.message,
        line,
        column,
      };
    }
  } catch (fileError) {
    // Handle file reading errors
    const error = fileError as Error;
    return {
      valid: false,
      error: error.message.includes('No such file') || error.message.includes('ENOENT')
        ? `File not found: ${filePath}`
        : `Error reading file: ${error.message}`,
    };
  }
}

