/**
 * Tests for YAML validation functionality.
 */

import { describe, test, expect } from "bun:test";
import { validateYaml } from "./utils";

describe("validateYaml", () => {
  test("returns valid: true for valid YAML file", async () => {
    const result = await validateYaml("test/fixtures/valid.yaml");
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid: false for invalid YAML with indentation error", async () => {
    const result = await validateYaml("test/fixtures/invalid-indent.yaml");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns valid: false for invalid YAML with syntax error", async () => {
    const result = await validateYaml("test/fixtures/invalid-syntax.yaml");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for non-existent file", async () => {
    const result = await validateYaml("test/fixtures/non-existent.yaml");
    expect(result.valid).toBe(false);
    expect(result.error).toContain("File not found");
  });

  test("handles empty file appropriately", async () => {
    const result = await validateYaml("test/fixtures/empty.yaml");
    expect(result.valid).toBe(true);
  });

  test("handles file paths with spaces", async () => {
    const result = await validateYaml("test/fixtures/file with spaces.yaml");
    expect(result.valid).toBe(false);
    expect(result.error).toContain("File not found");
  });

  test("handles absolute paths", async () => {
    const absolutePath = `${process.cwd()}/test/fixtures/valid.yaml`;
    const result = await validateYaml(absolutePath);
    expect(result.valid).toBe(true);
  });
});

