/**
 * CLI entry point for YAML validation.
 */
import { validateYaml } from "./utils";

const filePath = process.argv[2];

if (!filePath) {
  console.error("Usage: bun run validate-yaml <file.yaml>");
  process.exit(1);
}

const result = await validateYaml(filePath);

if (result.valid) {
  console.log(`✓ Valid YAML: ${filePath}`);
  process.exit(0);
} else {
  const location = result.line
    ? ` at line ${result.line}${result.column ? `:${result.column}` : ""}`
    : "";
  console.error(`✗ Invalid YAML: ${filePath}${location}`);
  console.error(`  ${result.error}`);
  process.exit(1);
}

