+      const lineMatch = error.message.match(/line[:\s]+(\d+)/i);
+      const columnMatch = error.message.match(/column[:\s]+(\d+)/i);
+      const lineColonMatch = error.message.match(/(\d+):(\d+)/);
+
+      if (lineMatch) {
+        line = parseInt(lineMatch[1], 10);
+      }
+      if (columnMatch) {
+        column = parseInt(columnMatch[1], 10);
+      }
+      if (lineColonMatch && !line) {
+        line = parseInt(lineColonMatch[1], 10);
+        column = parseInt(lineColonMatch[2], 10);
+      }
+
+      return {
+        valid: false,
+        error: error.message,
+        line,
+        column,
+      };
+    }
+  } catch (fileError) {
